  "implementation": "def solve(case):
    nodes = case['nodes']
    core_dist = case['core_distance']
    distances = case['distances']
    n = len(nodes)
    if n == 0:
        raise ValueError('No nodes')
    # Build distance lookup
    dist_dict = {}
    for a, b, d in distances:
        key = tuple(sorted((a, b)))
        dist_dict[key] = d
    edges = []
    for i in range(n):
        for j in range(i+1, n):
            a, b = sorted((nodes[i], nodes[j]))
            d = dist_dict[(a, b)]
            mutual = max(core_dist[a], core_dist[b], d)
            edges.append((mutual, a, b))
    edges.sort(key=lambda e: (e[0], e[1], e[2]))
    parent = list(range(n))
    rank = [0]*n
    node_to_idx = {node: idx for idx, node in enumerate(nodes)}
    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x
    def union(x, y):
        rx, ry = find(x), find(y)
        if rx == ry:
            return False
        if rank[rx] < rank[ry]:
            parent[rx] = ry
        elif rank[rx] > rank[ry]:
            parent[ry] = rx
        else:
            parent[ry] = rx
            rank[rx] += 1
        return True
    mst_edges = []
    total_weight = 0.0
    for weight, a, b in edges:
        if len(mst_edges) == n-1:
            break
        ia = node_to_idx[a]
        ib = node_to_idx[b]
        if union(ia, ib):
            mst_edges.append([a, b, weight])
            total_weight += weight
    if len(mst_edges) != n-1:
        raise ValueError('Graph is disconnected')
    return {'mst_edges': mst_edges, 'total_weight': total_weight}
